  },
  "remediation": {
    "remediation_steps": [
      {
        "step_number": 1,
        "title": "Validate Access and Kubernetes Context",
        "description": "Ensure the operator has the required ProdOperations role and that kubectl is pointed at the production cluster in us-east-1.",
        "commands": [
          "kubectl config current-context",
          "aws sts get-caller-identity",
