        "step_number": 2,
        "title": "Assess Storage Utilization and Identify Exhaustion Sources",
        "description": "Query S3 bucket metrics and pod volume usage to confirm the storage exhaustion root cause and locate the offending prefixes.",
        "commands": [
          "aws cloudwatch get-metric-statistics --namespace AWS/S3 --metric-name BucketSizeBytes --dimensions Name=BucketName,Value=analytics-pipeline-data --statistics Average --period 300 --start-time $(date -u -d '-1h' +%Y-%m-%dT%H:%M:%SZ) --end-time $(date -u +%Y-%m-%dT%H:%M:%SZ)",
          "kubectl exec -n analytics $(kubectl get pod -l app=analytics-pipeline -o jsonpath='{.items[0].metadata.name}') -- df -h",
          "aws s3api list-objects --bucket analytics-pipeline-data --query 'Contents[?Size>`1000000000`].[Key,Size]' --output table"
