        "step_number": 3,
        "title": "Enforce Write Freeze on Analytics Pipeline",
        "description": "Temporarily block new write operations to prevent further storage consumption while remediation proceeds.",
        "commands": [
          "kubectl -n analytics patch configmap pipeline-config -p '{\"data\":{\"WRITE_FREEZE\":\"true\"}}'",
          "kubectl rollout restart deployment/analytics-pipeline"
        ],
        "verification": [
          "ConfigMap key WRITE_FREEZE is set to \"true\"",
          "All analytics-pipeline pods report annotation write-freeze=enabled"
        ]
      },
