        "step_number": 4,
        "title": "Promote Read\u2011Replica to Primary for the Backend Store",
        "description": "Promote the standby replica (RDS or DynamoDB) to become the writable primary before any primary node is taken down.",
        "commands": [
          "aws rds promote-read-replica --db-instance-identifier analytics-pipeline-replica",
          "aws dynamodb update-table --table-name analytics-events --stream-specification StreamEnabled=true,StreamViewType=NEW_AND_OLD_IMAGES"
        ],
        "verification": [
          "RDS instance status changes to 'available' and role = primary",
          "DynamoDB table shows StreamEnabled=true"
        ]
      },
