        "title": "Perform Controlled Node Reboot",
        "description": "Cordon and drain the affected worker node, then issue a reboot via AWS SSM. This clears any lingering filesystem locks after the write freeze.",
        "commands": [
          "kubectl cordon <node-name>",
          "kubectl drain <node-name> --ignore-daemonsets --delete-emptydir-data",
          "aws ssm send-command --instance-ids $(aws ec2 describe-instances --filters Name=private-dns-name,Values=<node-name> --query 'Reservations[].Instances[].InstanceId' --output text) --document-name AWS-RunShellScript --parameters commands='sudo reboot'"
        ],
        "verification": [
          "Node shows NotReady status during drain",
          "Node returns to Ready status after reboot",
          "No pods remain in CrashLoopBackOff on the node"
        ]
      },
      {
        "step_number": 6,
        "title": "Remove Write Freeze and Validate Service Health",
        "description": "Re\u2011enable writes, restart the deployment, and run health checks to confirm normal operation.",
        "commands": [
          "kubectl -n analytics patch configmap pipeline-config -p '{\"data\":{\"WRITE_FREEZE\":\"false\"}}'",
          "kubectl rollout restart deployment/analytics-pipeline",
          "curl -sSf https://analytics-pipeline.internal/healthz",
          "kubectl logs -l app=analytics-pipeline --since=5m | grep ERR_STORAGE_EXHAUSTION_333 || echo 'No storage errors'"
        ],
        "verification": [
          "ConfigMap WRITE_FREEZE is \"false\"",
          "All pods report READY=1/1 and Running",
          "Health endpoint returns HTTP 200 with body 'OK'",
          "Log grep returns no storage exhaustion errors"
        ]
      }
