        {
          "step_number": 1,
          "description": "Undo deployment image to previous tag",
          "commands": [
            "kubectl rollout undo deployment/analytics-pipeline"
          ],
          "verification": [
            "Deployment revision rolls back to previous version",
            "Pods start with the prior container image"
          ]
        },
        {
          "step_number": 2,
          "description": "Demote promoted replica and re\u2011activate original primary",
          "commands": [
            "aws rds modify-db-instance --db-instance-identifier analytics-pipeline-primary --apply-immediately --no-multi-az",
            "aws rds reboot-db-instance --db-instance-identifier analytics-pipeline-primary",
            "aws dynamodb update-table --table-name analytics-events --stream-specification StreamEnabled=false"
          ],
          "verification": [
            "Original primary reports status 'available' and role = primary",
            "Promoted replica reverts to read\u2011only mode"
          ]
        },
        {
          "step_number": 3,
