          "verification": [
            "ConfigMap WRITE_FREEZE key equals \"false\""
          ]
        },
        {
          "step_number": 4,
          "description": "Validate storage metrics have stabilized",
          "commands": [
            "aws cloudwatch get-metric-statistics --namespace AWS/S3 --metric-name BucketSizeBytes --dimensions Name=BucketName,Value=analytics-pipeline-data --statistics Average --period 300 --start-time $(date -u -d '-30m' +%Y-%m-%dT%H:%M:%SZ) --end-time $(date -u +%Y-%m-%dT%H:%M:%SZ)"
